it('logs validation constraints without input values', async () => {
  const warn = jest.spyOn(log, 'warn').mockImplementation(() => {});
  try {
    const registry = new ToolRegistry();
    registry.register({name: 'weather', description: 'Weather', inputSchema: {type: 'object', properties: {location: {type: 'string'}}}}, async () => 'forecast');
